<div class="admin-page-head"><div><span class="eyebrow">سفارش / <?= CHtml::encode($order->order_number) ?></span><h1>جزئیات سفارش</h1><p>ثبت در <?= CHtml::encode(JalaliDate::format($order->created_at)) ?></p></div><?= CHtml::link('بازگشت به سفارش‌ها',array('adminOrder/index'),array('class'=>'btn btn-outline','data-pjax'=>'1')) ?></div>
<div class="admin-form-grid"><div class="form-main"><section class="panel"><h2>اقلام سفارش</h2><?php $this->widget("AdminTable",array("type"=>"order-items","context"=>array("order"=>$order->id))); ?><div class="summary-row total"><strong>مبلغ کل</strong><strong><?= Money::format($order->total) ?></strong></div></section>
<section class="panel"><h2>اطلاعات خریدار</h2><div class="spec-table">
<div class="spec-row"><strong>نام</strong><span><?= CHtml::encode($order->customer_name) ?></span></div>
<div class="spec-row"><strong>ایمیل</strong><span dir="ltr"><?= CHtml::encode($order->customer_email) ?></span></div>
<div class="spec-row"><strong>تلفن</strong><span dir="ltr"><?= CHtml::encode($order->customer_phone) ?></span></div>
<div class="spec-row"><strong>نشانی</strong><span><?= CHtml::encode($order->province.' / '.$order->city) ?> · <?= nl2br(CHtml::encode($order->shipping_address)) ?></span></div>
<div class="spec-row"><strong>یادداشت</strong><span><?= nl2br(CHtml::encode($order->notes)) ?></span></div></div></section></div>
<aside class="form-aside"><section class="panel"><h2>وضعیت سفارش</h2><?= OrderPresentation::badge($order->status) ?>
<?php if($order->nextStatuses()): ?><?= CHtml::beginForm(array('adminOrder/status','id'=>$order->id),'post',array('data-confirm'=>'تغییر وضعیت و ثبت گردش مالی/انبار انجام شود؟')) ?>
<div class="field"><label>تغییر وضعیت</label><?= CHtml::dropDownList('status',null,$order->nextStatuses()) ?></div><?= CHtml::submitButton('ثبت وضعیت',array('class'=>'btn btn-primary btn-block')) ?><?= CHtml::endForm() ?>
<?php else: ?><p class="muted note">این سفارش در وضعیت نهایی است و قابل تغییر نیست.</p><?php endif; ?>
<?php if($order->reserved_until): ?><div class="reservation-notice">پایان رزرو: <?= CHtml::encode(JalaliDate::format($order->reserved_until)) ?> (تهران)</div><?php endif; ?><div class="summary-row"><span>جمع کالاها</span><strong><?= Money::format($order->subtotal) ?></strong></div><div class="summary-row"><span>تخفیف کد <?= CHtml::encode($order->coupon_code) ?></span><strong><?= Money::format($order->discount_total) ?></strong></div></section><section class="panel"><h2>تاریخچه وضعیت</h2><?php foreach($events as $event): ?><p class="order-event"><strong><?= CHtml::encode(isset($order->statuses()[$event['to_status']])?$order->statuses()[$event['to_status']]:$event['to_status']) ?></strong><small><?= CHtml::encode(JalaliDate::format($event['created_at'])) ?></small></p><?php endforeach; ?></section></aside></div>

<section class="panel"><h2>ارسال و رهگیری مرسوله</h2><p>هزینه ارسال: <?= Money::format($order->shipping_total) ?> · کد پستی: <?= CHtml::encode($order->postal_code) ?></p><?= CHtml::beginForm(array('adminOrder/tracking','id'=>$order->id),'post') ?><label for="tracking_code">کد رهگیری مرسوله</label><?= CHtml::textField('tracking_code',$order->tracking_code,array('maxlength'=>190)) ?><?= CHtml::submitButton('ذخیره کد رهگیری',array('class'=>'btn btn-primary')) ?><?= CHtml::endForm() ?></section>
